// Color conversion taken from https://www.shadertoy.com/view/7syczc

// linear to nonlinear sRGB
float linear_to_nonlinear_srgb(float x)
{
    if (x >= 0.0031308)
        return (1.055) * pow(x, 1.0/2.4) - 0.055;
    else
        return 12.92 * x;
}

vec3 linear_to_nonlinear_srgb(vec3 x)
{
    return vec3(linear_to_nonlinear_srgb(x.x), linear_to_nonlinear_srgb(x.y), linear_to_nonlinear_srgb(x.z));
}

// nonlinear to linear sRGB
float nonlinear_to_linear_srgb(float x)
{
    if (x >= 0.04045)
        return pow((x + 0.055)/(1.0 + 0.055), 2.4);
    else 
        return x / 12.92;
}

vec3 nonlinear_to_linear_srgb(vec3 x)
{
    return vec3(nonlinear_to_linear_srgb(x.x), nonlinear_to_linear_srgb(x.y), nonlinear_to_linear_srgb(x.z));
}

float luminance(vec3 color) {
  return dot(color, vec3(0.2126, 0.7152, 0.0722));
}

float lum_alpha(float a, float l0, float l1)
{
    float diff = (l1 - l0)*1.2; // The 1.2 was found empirically, could be related to that gamma 2.2 is really close to sRGB curve.
    return (diff > 0.) ? pow(a, 1. + diff) : 1. - pow(1. - a, 1. - diff);
}

// Mixes two linear sRGB colors with luminance adjustment so that the result looks kinda close to mixing in sRGB color space (sans the artifacts).
// Based on trial and error, not science :)
vec3 lum_mix(vec3 linC0, vec3 linC1, float a)
{
    // Fudge the alpha based on the relative luminance of the colors to be blended.
    float l0 = luminance(linC0);
    float l1 = luminance(linC1);

    // The first version of this shader used this, but it is not symmetrical and the <1 part did not look very good.
    // The asymmetry also meant that depending on order, c0 and c1 would blend differently.
//  float ff = clamp(1.0 + (l1 - l0), 0.5, 2.0);
//  a = pow(a, ff);

    a = lum_alpha(a, l0, l1);

    return mix(linC0, linC1, a);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord;
    vec2 cells = floor(vec2(iResolution.x / 30.0, iResolution.y / 30.0f));
    vec2 cs = vec2(iResolution.x / cells.x, iResolution.y / cells.y);

    // B&W
//    vec3 L = vec3(1, 1, 1), R = vec3(0, 0, 0);

    // R&G (this makes the dark fringin obvious in sRGB, especially w/: feather = 5)
//    vec3 L = vec3(1, 0, 0), R = vec3(0, 1, 0);

    // Blue->Yellow
    vec3 L = vec3(76./255., 6./255., 252./255.), R = vec3(252./255., 216./255., 2./255.);

    // Grid
    float rowOffset = cs.x*0.5;
    vec2 cell;
    cell.y = floor(uv.y/cs.y);
    cell.x = floor((uv.x + cell.x * offset)/cs.x);  
//    vec2 cell = floor(uv/cs);
    vec2 loc = uv - cell*cs;
    vec2 nc = cell/(cells-vec2(1.));

    // Ring
    float th = 1.0; // ring thickness
    float feather = 1.; // ring feather, aka "blur"
    float d = length(loc- cs*0.5);
    float a = clamp((abs(d - min(cs.x,cs.y)*0.25) + 0.5 - th*0.5) / feather, 0.,1.);

    // Interpolate bg/fg per grid cell.
    // interpolate grid colors in sRGB
//    vec3 c0 = mix(L,R,nc.x);
//    vec3 c1 = mix(L,R,nc.y);
    // interpolate grid colors in lum comp linear sRGB
    vec3 linL = nonlinear_to_linear_srgb(L);
    vec3 linR = nonlinear_to_linear_srgb(R);
    vec3 c0 = linear_to_nonlinear_srgb(lum_mix(linL, linR, nc.x));
    vec3 c1 = linear_to_nonlinear_srgb(lum_mix(linL, linR, nc.y));


    vec3 col = vec3(0);

    int opt = int(iMouse.x / (iResolution.x/4.));
    if (opt == 0 || opt == 3) {
        // linear sRGB
        col = linear_to_nonlinear_srgb(mix(nonlinear_to_linear_srgb(c0),nonlinear_to_linear_srgb(c1),a));
    } else if (opt == 1) {
        // sRGB
        col = mix(c0,c1,a);
    } else if (opt == 2) {
        // Luminance compensated linear sRGB
        // The goal of this version is to look as close to the sRGB case, but without the dimming during blending.
        // Try R&G version above with feather = 5 to see the dimming issue.
        vec3 lc0 = nonlinear_to_linear_srgb(c0);
        vec3 lc1 = nonlinear_to_linear_srgb(c1);
        col = linear_to_nonlinear_srgb(lum_mix(lc0, lc1, a));
    }

    // visualize mode
    for (int i = 0; i < 4; i++) {
        vec2 pp = vec2(20. + float(i)*20., 20.);
        d = length(uv - pp);
        float a = 0.;
        if (i == opt)
            a = 1. - clamp(d - 5. + 0.5, 0.,1.);
        else
            a = (1. - clamp((abs(d - 5.) + 0.5 - 1.), 0.,1.)) * 0.5;
        col = mix(col,vec3(1.),a);
    }

    // Output to screen
    fragColor = vec4(col, 1.0);
}
